### PricingCard.tsx
```tsx
import { useState } from 'react';

interface PricingCardProps {
  isMonthly: boolean;
  onChange: (value: boolean) => void;
}

const PricingCard: React.FC<PricingCardProps> = ({ isMonthly, onChange }) => {
  const [selectedPeriod, setSelectedPeriod] = useState<'monthly' | 'yearly'>('monthly');

  const togglePeriod = () => {
    setSelectedPeriod(prev => prev === 'monthly' ? 'yearly' : 'monthly');
  };

  const price = selectedPeriod === 'monthly' ? 19.99 : 199.99;

  return (
    <div className="max-w-md w-full bg-white rounded-lg shadow-md overflow-hidden border border-gray-100">
      <div className="p-6">
        <h1 className="text-2xl font-semibold text-gray-800 mb-2">Pro Plan</h1>

        <div className="flex justify-between items-center mb-4">
          <button
            onClick={() => onChange(true)}
            className={`px-4 py-2 text-sm font-medium rounded-md transition-colors ${
              isMonthly 
                ? 'bg-blue-600 text-white' 
                : 'text-gray-500 hover:text-gray-700'
            }`}
          >
            Monthly
          </button>
          <button
            onClick={() => onChange(false)}
            className={`px-4 py-2 text-sm font-medium rounded-md transition-colors ${
              !isMonthly 
                ? 'bg-blue-600 text-white' 
                : 'text-gray-500 hover:text-gray-700'
            }`}
          >
            Yearly
          </button>
        </div>

        <div className="mb-6">
          <span className="text-4xl font-bold text-gray-900">${price}</span>
          <span className="text-lg text-gray-500 ml-1">/month</span>
        </div>

        <ul className="space-y-3 mb-6">
          {[
            'Unlimited projects',
            'Priority support',
            'Advanced analytics'
          ].map((feature, index) => (
            <li key={index} className="flex items-center">
              <svg className="w-5 h-5 text-accent mr-3" fill="currentColor" viewBox="0 0 20 20">
                <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" />
              </svg>
              {feature}
            </li>
          ))}
        </ul>

        <button className="w-full py-3 px-4 bg-accent text-white font-semibold rounded-md hover:bg-blue-700 transition-colors">
          Buy Now
        </button>
      </div>
    </div>
  );
};

export default PricingCard;
```
